import { OrderRepository, parseCursor } from './repository';
import { ListRequest, Page } from './types';

export class OrderHandler {
  constructor(private readonly repository: OrderRepository) {}

  list(request: ListRequest): Page {
    const { tenant, limit } = request;
    if (
      typeof tenant !== 'string' ||
      tenant.length === 0 ||
      !Number.isInteger(limit) ||
      limit < 1 ||
      limit > 100
    ) {
      throw new Error('invalid request');
    }

    // Throws Error('invalid request') for a malformed cursor.
    const cursor = parseCursor(request.cursor);
    const cursorString = cursor === null ? undefined : `${cursor.createdAt}|${cursor.id}`;

    // The repository applies the tenant filter and resumes strictly after the
    // cursor position; the page is then cut to `limit`.
    const matching = this.repository.list(tenant, cursorString);
    const items = matching.slice(0, limit);
    const nextCursor =
      matching.length > limit
        ? `${items[items.length - 1].createdAt}|${items[items.length - 1].id}`
        : null;

    return { items, nextCursor };
  }
}

